# Candidate (B3) for TASK-SHIP-024 (tracking_endpoint_path_migration)
def build_request(data):
    return {
        'path': '/v2/logistics/tracking_endpoint_path_migration/task-ship-024',
        'body': {
            'shipment_milestone_envelope': {
                'parcel_id': data['parcel_id'],
                'weight_grams': int(data['weight_grams']),
                'length_cm': int(data['length_cm']),
                'carrier_iso': data['carrier_code'],
                'route_address': data['street_address']
            }
        },
        'headers': {
            'X-Shipment-Idempotency': data['idempotency_key']
        }
    }

def generate_label(data):
    return build_request(data)

def get_health_status():
    return {'path': '/health', 'status': 'ok'}
